fetch('plants.json').then((r) => r.json()).then((plants) => {
  const due = plants.filter((p) => p.water_every <= 3);
  document.querySelector('.dry-spell').hidden = due.length > 0;
  document.getElementById('plants').innerHTML = plants.map((p) => `<li>${p.name}: every ${p.water_every} days</li>`).join('');
});

